effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

           float hash( vec2 p )
        {
        	float h = dot(p + progressa * 0.0001,vec2(127.1,311.7));
            return fract(sin(h)*43758.5453123);
        }
        float hash2( vec2 p )
        {
        	float h = dot(p ,vec2(127.1,311.7));
            return fract(sin(h)*43758.5453123);
        }

        float noise( in vec2 p )
        {
            vec2 i = floor( p );
            vec2 f = fract( p );

        	vec2 u = f*f*(3.0-2.0*f);

            return mix( mix( hash( i + vec2(0.0,0.0) ), 
                             hash( i + vec2(1.0,0.0) ), u.x),
                        mix( hash( i + vec2(0.0,1.0) ), 
                             hash( i + vec2(1.0,1.0) ), u.x), u.y);
        }


   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        // if (adaptive) { 
        TanRyu = acScreenNorm; 
        // }
        // else { 
        // TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        // TanRyu.y*=acLayerSize.y/acLayerSize.x;
        // }

        TanRyu /= scale;
        // TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

        if(progressa <= 0.0) { gl_FragColor = texture2DCv(inputImg.texture,acScreenNorm); }
        else if(progressa >= 0.0001) { 

    	vec4 fragColor;

    	      vec2 uv = TanRyu;

            float glitch = hash2(floor(progressa * 4.0 - uv * 20.0) / 20.0);
            uv += pow(fract(glitch + progressa * 0.1), 30.0);

            float n = pow((noise(uv * 150.0) + noise(uv * 350.0)) * 0.5, 3.0);
            n *= abs(sin(uv.y * 250.0 + progressa * 2.0));
            float offset = sign(sin(uv.x * 6.0 + progressa * 3.0)) * 0.1;
            offset += sign(sin(uv.y * 10.0 + uv.x * 14.5 + progressa * 20.0)) * 0.1;
            offset += sign(sin(sin(progressa) * uv.y * 12.0 - uv.x * 22.0 - progressa * 40.0)) * 0.2;
            offset = pow(offset - 0.5, 4.0);

            n *= min(1.0, floor((1.5 - uv.y + offset) * 3.0) / 3.0);

            float waver = abs(noise(vec2(progressa * 3.7)) * 2.0);
            n *= pow(fract(floor(uv.y * 15.0) / 15.0 + progressa * 0.3) * waver * 0.4 + 0.4, 0.65);
            n *= 0.75 + waver * 0.125;
            n = clamp(n, 0.0, 1.0);

        	fragColor = vec4(n);


         	// const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*fragColor.a;

    	// vec4 factorx = mix(fragColor,gradmap,alphab);
    	vec4 factor = mix(texColorX,fragColor,alpha);

        vec4 resultfinal;
        // if( blendMode==0 ) {                // normal
            // resultfinal = (factor * bright) * texColor.a;
        // } else if( blendMode==1 ) {         // multiply
            // factor *= bright;
            // vec4 c = factor + vec4(1.)*(1.-factor.a);
            // resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        // } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        // }

    	gl_FragColor = resultfinal;
    	}
    }
